        { "cycle.ts", "interface ListNode {\n  next: ListNode | null;\n}\n\nfunction hasCycle(node: ListNode): boolean {\n  let hare: ListNode | null = node;\n  let tortoise: ListNode | null = node;\n  while (true) {\n    if (hare!.next === null) {\n      return false;\n    }\n    tortoise = tortoise!.next;\n    hare = hare!.next!.next;\n    if (hare === tortoise) {\n      return true;\n    }\n  }\n}\n\nfunction list(count: number, looped: boolean): ListNode {\n  const first: ListNode = { next: null };\n  let last = first;\n  for (let i = 1; i < count; i++) {\n    last.next = { next: null };\n    last = last.next;\n  }\n  if (looped) {\n    last.next = first;\n  }\n  return first;\n}\n\nconsole.log(`${hasCycle(list(3, true)) ? \"cycle\" : \"no cycle\"} / ${hasCycle(list(4, false)) ? \"cycle\" : \"no cycle\"}`);\n", "logic-js-two-steps-one-asked", 9, 9, 1, "    if (hare === null || hare!.next === null) {" },
