    [Theory]
    [MemberData(nameof(Mistakes))]
    public void APointerMovedTwoButAskedAboutOneIsFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The searches asking both; one asking while fast and fast.successor; one asking fast != null &amp;&amp; fast.next != null;
    /// every other value walked, asked about first; and PowerShell's search without strict mode, where a property of $null is
    /// $null and the answer is right.
    /// </summary>
    [Theory]
    [InlineData("cycle.c", "#include <stdio.h>\n\nstruct node {\n    struct node *next;\n};\n\nint has_cycle(struct node *node) {\n    struct node *hare = node, *tortoise = node;\n    while (1) {\n        if (hare == NULL || hare->next == NULL) return 0;\n        tortoise = tortoise->next;\n        hare = hare->next->next;\n        if (hare == tortoise) return 1;\n    }\n}\n\nint main(void) {\n    struct node looped[3], straight[4];\n    looped[0].next = &looped[1];\n    looped[1].next = &looped[2];\n    looped[2].next = &looped[0];\n    for (int i = 0; i < 3; i++) straight[i].next = &straight[i + 1];\n    straight[3].next = NULL;\n    printf(\"%s / %s\\n\", has_cycle(looped) ? \"cycle\" : \"no cycle\", has_cycle(straight) ? \"cycle\" : \"no cycle\");\n    return 0;\n}\n")]
